INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_it_wifi_devices','campus_it','Wireless Network Online Device Limit','Personal accounts support up to five devices online simultaneously; old terminals that have been offline for an extended period can be unlinked from the self-service page.','offline://campus/post_it_wifi_devices','2026-08-05T09:10:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_it_mfa_recovery','campus_it','Two-Factor Authentication Recovery After Changing Phones','Faculty and students who cannot access their old authenticator may clear the original binding and register a new device after identity verification.','offline://campus/post_it_mfa_recovery','2026-07-02T11:50:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_it_cloud_quota','campus_it','Student Cloud Drive Quota Reminder','After the storage capacity is exceeded, existing files can still be downloaded, but new uploads will be paused; the Recycle Bin also uses quota.','offline://campus/post_it_cloud_quota','2026-08-15T13:05:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_it_lab_image','campus_it','Fall Public Computer Lab Software Image','The new image includes drafting, numerical computing, and programming tools, with terminal deployment completed Friday night.','offline://campus/post_it_lab_image','2026-08-27T14:40:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_it_phishing_headers','campus_it','What information to retain when reporting a suspicious email','The security ticket retains the email headers and link text, and does not collect passwords, verification codes, or complete identification numbers.','offline://campus/post_it_phishing_headers','2026-07-29T16:05:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_residence_hotwater','residential_life','Hot water maintenance on the lower floors of Building 5','Valve maintenance is scheduled for early Tuesday morning, affecting the first through third floors and expected to last two hours.','offline://campus/post_residence_hotwater','2026-08-28T18:20:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_residence_laundry','residential_life','Equipment status in the north laundry room','Two dryers are awaiting parts. All other washing and drying equipment remains available, and erroneous charges will be refunded automatically.','offline://campus/post_residence_laundry','2026-08-24T19:10:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_residence_visitors','residential_life','Registration for the residence hall communal visitor area','Visitors may enter the communal visitor area after their identities are verified at the front desk. New registrations stop at 9:30 p.m.','offline://campus/post_residence_visitors','2026-08-13T08:45:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_residence_filter_cleaning','residential_life','Central air-conditioner filter cleaning week','Each floor will collect and return removable filters by label. Cleaning registrations use room numbers only and do not record personal belongings.','offline://campus/post_residence_filter_cleaning','2026-07-25T12:15:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_residence_lock_record_9Q4V','residential_life','Summer door-lock repair tickets made read-only','Repair tickets completed in August can no longer be edited. Residents may still view the part numbers and actual repair dates.','offline://campus/post_residence_lock_record_9Q4V','2026-08-30T17:10:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_transport_weekend','campus_transport','Weekend Shuttle Stop Changes','A library west entrance stop will be added on Saturday; the last Sunday service runs earlier than on weekdays, and no advance reservation is required.','offline://campus/post_transport_weekend','2026-08-19T18:25:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_transport_bike_parking','campus_transport','Bike Racks South of Building A3 Temporarily Closed','During construction, please use the parking area at the east end of Ginkgo Road; additional nighttime lighting has been installed in the temporary area.','offline://campus/post_transport_bike_parking','2026-08-22T07:50:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_transport_code_fallback','campus_transport','Verification Method When the Transit QR Code Malfunctions','If the transit QR code cannot be refreshed, you may verify the photo on your campus card; anomalies from the day will be summarized for the system maintenance staff.','offline://campus/post_transport_code_fallback','2026-07-09T14:55:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_transport_night_path','campus_transport','Nighttime Lighting Route in the East District','Lighting is continuous along the route from the gymnasium to the service hall, and the three help poles along the way have completed their monthly functionality checks.','offline://campus/post_transport_night_path','2026-08-11T20:05:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_transport_summer_record_5N8R','campus_transport','Summer Campus Bus Timetable Archive','The reduced service schedule has ended; the old page is only for verifying reimbursements and travel records for completed trips.','offline://campus/post_transport_summer_record_5N8R','2026-08-28T22:20:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_health_vaccine_days','health_center','Adult Vaccine Clinic Open Days','The clinic schedules two afternoons each month, and medical staff will verify previous vaccination records and contraindication information.','offline://campus/post_health_vaccine_days','2026-08-07T10:25:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_health_dental_scope','health_center','Campus Hospital Dental Clinic Service Scope','Basic examinations and cleanings can be completed on campus; doctors will issue referral recommendations for complex imaging or surgery.','offline://campus/post_health_dental_scope','2026-07-18T08:20:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_health_report_pickup','health_center','Electronic and Paper Copies of Health Examination Reports','The electronic report is added to the personal health account, while the stamped paper copy can be collected with a pickup code in the outpatient lobby.','offline://campus/post_health_report_pickup','2026-08-10T12:40:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_health_pharmacy_evening','health_center','Extended Pharmacy Service on Weekdays','Regular prescriptions can be picked up before 8:00 p.m.; refrigerated medications and special prescriptions are still dispensed at the daytime window.','offline://campus/post_health_pharmacy_evening','2026-08-21T11:00:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_health_sleep_replay','health_center','Public Replay of Sleep Health Lecture','The recording includes an anonymized Q&A summary; individual consultations held at the event were not published.','offline://campus/post_health_sleep_replay','2026-07-29T19:30:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_career_resume_clinic','career_center','New Time Slots for Engineering Resume Clinic','Consultations are 20 minutes each, with feedback focused on project descriptions and layout; personal experiences will not be written for applicants.','offline://campus/post_career_resume_clinic','2026-08-18T16:15:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_career_fair_map','career_center','Fall Internship Recruitment Fair Booth Map','The booth map is organized by industry and includes links to online positions; booth removal changes are updated on the entrance screens.','offline://campus/post_career_fair_map','2026-08-24T14:25:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_career_interview_rooms','career_center','On-Campus Interview Soundproof Room Equipment','The room provides a wired network, fill light, and a ten-minute setup buffer. Food and drinks are not permitted in the equipment area.','offline://campus/post_career_interview_rooms','2026-07-30T10:45:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_career_assessment_privacy','career_center','Boundaries on the Use of the Career Interest Assessment','The report is intended for discussion during the individual consultation. It is not automatically shared with recruiters and does not constitute a conclusion about job fit.','offline://campus/post_career_assessment_privacy','2026-06-26T15:55:00+08:00');
INSERT INTO official_account_posts(post_id,account_id,title,summary,url,published_at) VALUES('post_career_portfolio_talk','career_center','Engineering Project Portfolio Sharing Session','Alumni will present summaries of public projects, version trade-offs, and approaches to explaining projects in interviews. Unpublished drawings will not be collected.','offline://campus/post_career_portfolio_talk','2026-08-29T15:10:00+08:00');
